(()=>{const angles=[['front view','正面'],['front-right quarter view','右前45°'],['right side view','右侧90°'],['back-right quarter view','右后45°'],['back view','背面'],['back-left quarter view','左后45°'],['left side view','左侧90°'],['front-left quarter view','左前45°']],heights=[['low-angle shot','低机位'],['eye-level shot','平视'],['elevated shot','稍高俯视'],['high-angle shot','高机位俯视']],distances=[['close-up','近景'],['medium shot','标准距离'],['wide shot','远景']];function config(s){const key=s.activeView||'master';s.cameraControls??={};return s.cameraControls[key]??={enabled:true,azimuth:/reverse/i.test(key)?'back view':'front-left quarter view',elevation:/close/i.test(key)?'low-angle shot':'eye-level shot',distance:/close/i.test(key)?'close-up':'medium shot'};}function draw(){const s=currentScene();if(!s||s.activeView==='master'||!s.activeView||s.imageModel==='zimage'||s.editIntent==='retouch')return;const button=document.querySelector('#sceneGenerate');if(!button)return;const c=config(s),box=document.createElement('div');box.className='card';box.style.cssText='margin:12px 0;padding:16px';box.innerHTML='<b>机位视角控制 · 2511 Multiple-Angles</b><label style="display:flex;gap:8px;align-items:center;margin:12px 0"><input data-enable type="checkbox" style="width:18px;flex:none">使用视角 LoRA</label><div style="display:flex;gap:12px;flex-wrap:wrap">'+[['azimuth','方向',angles],['elevation','高度',heights],['distance','远近',distances]].map(([key,title,options])=>'<label style="width:auto">'+title+'<select data-angle="'+key+'" style="width:auto">'+options.map(([v,n])=>'<option value="'+v+'">'+n+'</option>').join('')+'</select></label>').join('')+'</div><p class="subtle">使用配套2511视角LoRA与4步加速。方向相对输入图；单图无法确保隐藏区域完全一致，生成后检查建筑与地标。此模式采用专用角度词，普通场景长提示词不参与。</p>';const anchor=button.closest('#scenePreviewGenerateActions')||button;anchor.before(box);const busy=sceneBusy(s.jobs?.[s.activeView]);const enabled=box.querySelector('[data-enable]');enabled.checked=c.enabled!==false;enabled.disabled=busy;enabled.onchange=e=>{c.enabled=e.target.checked;save();render();};box.querySelectorAll('[data-angle]').forEach(el=>{el.value=c[el.dataset.angle];el.disabled=busy||!c.enabled;el.onchange=e=>{c[el.dataset.angle]=el.value;save();};});}const previous=renderScenes;renderScenes=function(){previous();draw();};const oldFetch=frontFetch;frontFetch=async function(url,body){if(url==='/api/front-image'&&body?.resource_type==='scene'&&body.mode==='scene_edit'&&body.view_key!=='master'){const s=(data.scenes||[]).find(s=>s.id===body.character_id);if(s)body={...body,camera_control:{...config(s)}};}return oldFetch(url,body);};render();})();